query IssueByNumber($owner: String!, $repo: String!, $number: Int!) {
	repository(owner: $owner, name: $repo) {
		hasIssuesEnabled
		issue: issueOrPullRequest(number: $number) {
			__typename
			...on Issue{id,number,title,body,url,milestone{number,title,description,dueOn}}
			...on PullRequest{id,number,title,body,url,milestone{number,title,description,dueOn}}
		}
	}
}
